const MM={y:[['اختياري تماماً','مجاني، من غير أي دفع','التطبيق كله شغال من غير تسجيل','بيانات صفقاتك تفضل على موبايلك'],['Completely optional','Free, no payment ever','The app works fully without signing in','Your trade data stays on your phone'],['Totalement facultatif','Gratuit, aucun paiement','L\'app fonctionne sans connexion','Vos données de trades restent sur votre téléphone'],['Totalmente opcional','Gratis, sin pagos','La app funciona sin entrar','Tus datos de trades quedan en tu teléfono'],['Tamamen isteğe bağlı','Ücretsiz, ödeme yok','Uygulama girişsiz de çalışır','İşlem verilerin telefonunda kalır'],['کاملاً اختیاری','رایگان، بدون پرداخت','برنامه بدون ورود هم کار می‌کند','داده‌های معاملاتت روی گوشی می‌ماند'],['بالکل اختیاری','مفت، کوئی ادائیگی نہیں','ایپ سائن ان کے بغیر بھی چلتی ہے','ٹریڈ ڈیٹا آپ کے فون پر رہتا ہے'],['पूरी तरह वैकल्पिक','मुफ़्त, कोई भुगतान नहीं','ऐप बिना साइन इन के भी चलता है','ट्रेड डेटा आपके फोन पर रहता है']],
n:['مش اشتراك مدفوع ومش شرط لاستخدام التطبيق. التسجيل بيفتح مميزات المجتمع بس.','Not a paid subscription and not required to use the app. Signing in only unlocks community features.','Pas un abonnement payant, et non requis. La connexion débloque seulement les fonctions communautaires.','No es una suscripción de pago ni es obligatoria. Entrar solo desbloquea funciones de comunidad.','Ücretli abonelik değil, zorunlu da değil. Giriş yalnızca topluluk özelliklerini açar.','اشتراک پولی نیست و الزامی هم نیست. ورود فقط امکانات جامعه را باز می‌کند.','ادا شدہ سبسکرپشن نہیں اور لازمی بھی نہیں۔ سائن ان صرف کمیونٹی فیچر کھولتا ہے۔','यह सशुल्क सदस्यता नहीं है और ज़रूरी भी नहीं। साइन इन सिर्फ समुदाय सुविधाएँ खोलता है।'],
h:['ايه معنى تسجيل الدخول؟','What does signing in mean?','Que signifie se connecter ?','¿Qué significa entrar?','Giriş ne demek?','ورود یعنی چه؟','سائن ان کا مطلب کیا ہے؟','साइन इन का मतलब क्या है?']};
