const GQX={"wf": [[["Ouvrir l'accueil", "Regardez le prix de l'or et les sessions (Londres, New York) pour savoir quand le marché est actif."], ["Abrir Inicio", "Mira el precio del oro y las sesiones (Londres, Nueva York) para saber cuándo el mercado está activo."], ["Ana sayfayı aç", "Altın fiyatına ve seanslara (Londra, New York) bak, piyasanın ne zaman hareketli olduğunu gör."], ["خانه را باز کنید", "قیمت طلا و جلسات (لندن، نیویورک) را ببینید تا بدانید بازار کی فعال است."], ["ہوم کھولیں", "سونے کی قیمت اور سیشن (لندن، نیویارک) دیکھیں تاکہ پتا چلے مارکیٹ کب سرگرم ہے۔"], ["होम खोलें", "सोने का भाव और सेशन (लंदन, न्यूयॉर्क) देखें ताकि पता चले बाज़ार कब सक्रिय है।"]], [["Vérifier actus et calendrier", "Regardez le calendrier économique. Si une annonce importante approche, tenez-en compte avant tout trade."], ["Revisa noticias y calendario", "Mira el calendario económico. Si hay un dato importante cerca, tenlo en cuenta antes de cualquier operación."], ["Haber ve takvimi kontrol et", "Ekonomik takvime bak. Yakında önemli bir veri varsa işlemden önce hesaba kat."], ["اخبار و تقویم را ببینید", "تقویم اقتصادی را ببینید. اگر خبر مهمی نزدیک است، پیش از هر معامله در نظر بگیرید."], ["خبریں اور کیلنڈر دیکھیں", "اکنامک کیلنڈر دیکھیں۔ کوئی بڑی خبر قریب ہو تو ٹریڈ سے پہلے اسے مدنظر رکھیں۔"], ["खबरें और कैलेंडर देखें", "इकोनॉमिक कैलेंडर देखें। कोई बड़ी खबर नज़दीक हो तो किसी भी ट्रेड से पहले ध्यान रखें।"]], [["Analyser sur le graphique", "Touchez le graphique sur l'accueil pour l'analyse complète. Choisissez la paire et l'unité de temps, puis tracez vos niveaux."], ["Analiza en el gráfico", "Toca el gráfico en Inicio para el análisis completo. Elige el par y el marco temporal y dibuja tus niveles."], ["Grafikte analiz et", "Tam analiz için Ana sayfadaki grafiğe dokun. Pariteyi ve zaman dilimini seç, seviyelerini çiz."], ["روی نمودار تحلیل کنید", "برای تحلیل کامل روی نمودار صفحه خانه بزنید. جفت‌ارز و تایم‌فریم را انتخاب و سطوح خود را رسم کنید."], ["چارٹ پر تجزیہ کریں", "مکمل تجزیے کے لیے ہوم پر چارٹ دبائیں۔ جوڑی اور ٹائم فریم چنیں اور اپنی سطحیں کھینچیں۔"], ["चार्ट पर विश्लेषण करें", "पूरे विश्लेषण के लिए होम पर चार्ट दबाएं। जोड़ी और टाइमफ्रेम चुनें और अपने स्तर बनाएं।"]], [["Fixer votre plan", "Avant d'entrer, notez : prix d'entrée, stop et objectif."], ["Define tu plan", "Antes de entrar, escribe: precio de entrada, stop y objetivo."], ["Planını belirle", "Girmeden önce yaz: giriş fiyatı, zarar durdur ve hedef."], ["برنامه‌تان را مشخص کنید", "پیش از ورود بنویسید: قیمت ورود، حد ضرر و هدف."], ["اپنا پلان طے کریں", "داخل ہونے سے پہلے لکھیں: انٹری قیمت، اسٹاپ اور ٹارگٹ۔"], ["अपना प्लान तय करें", "एंट्री से पहले लिखें: एंट्री भाव, स्टॉप और टारगेट।"]], [["Calculer le risque", "Dans Outils : calculez la taille de position et le rapport risque/gain avant d'entrer."], ["Calcula el riesgo", "En Herramientas: calcula el tamaño de posición y la relación riesgo/beneficio antes de entrar."], ["Riski hesapla", "Araçlar'da: girmeden önce pozisyon boyutunu ve risk/getiri oranını hesapla."], ["ریسک را حساب کنید", "در ابزارها حجم معامله و نسبت ریسک به سود را پیش از ورود حساب کنید."], ["رسک کا حساب لگائیں", "ٹولز میں داخل ہونے سے پہلے پوزیشن سائز اور رسک ٹو ریوارڈ نکالیں۔"], ["रिस्क निकालें", "टूल्स में एंट्री से पहले पोज़ीशन साइज़ और रिस्क-टू-रिवॉर्ड निकालें।"]], [["Passer la liste de contrôle", "Dans Journal : cochez chaque point. S'il en manque un, le trade n'est pas prêt."], ["Pasa la lista de control", "En Diario: marca cada punto. Si falta uno, la operación no está lista."], ["Kontrol listesini geç", "Günlükte her maddeyi işaretle. Biri eksikse işlem hazır değildir."], ["فهرست بررسی را بگذرانید", "در دفترچه هر مورد را علامت بزنید. اگر موردی کم باشد، معامله آماده نیست."], ["چیک لسٹ مکمل کریں", "جرنل میں ہر نکتے پر نشان لگائیں۔ کوئی رہ جائے تو ٹریڈ تیار نہیں۔"], ["चेकलिस्ट पूरी करें", "जर्नल में हर बिंदु टिक करें। कोई छूटे तो ट्रेड तैयार नहीं।"]], [["Noter le trade", "Après la clôture, enregistrez-le dans Analyse (tableau des trades) : entrée, stop et sortie."], ["Registra la operación", "Al cerrarla, regístrala en Análisis (hoja de operaciones): entrada, stop y salida."], ["İşlemi kaydet", "Kapandıktan sonra Analiz'deki işlem tablosuna kaydet: giriş, zarar durdur ve çıkış."], ["معامله را ثبت کنید", "پس از بسته شدن، در تحلیل (جدول معاملات) ثبت کنید: ورود، حد ضرر و خروج."], ["ٹریڈ درج کریں", "بند ہونے کے بعد تجزیہ (ٹریڈ شیٹ) میں درج کریں: انٹری، اسٹاپ اور ایگزٹ۔"], ["ट्रेड दर्ज करें", "बंद होने के बाद विश्लेषण (ट्रेड शीट) में दर्ज करें: एंट्री, स्टॉप और एग्ज़िट।"]], [["Revoir et apprendre", "Regardez le taux de réussite et le R moyen dans Analyse, et notez vos leçons dans Journal. L'onglet Apprendre explique simplement."], ["Revisa y aprende", "Mira el porcentaje de acierto y el R medio en Análisis y anota lo aprendido en Diario. La pestaña Aprender lo explica fácil."], ["Gözden geçir ve öğren", "Analiz'de başarı oranına ve ortalama R'ye bak, notlarını Günlüğe yaz. Öğren sekmesinde sade açıklamalar var."], ["مرور و یادگیری", "درصد موفقیت و میانگین R را در تحلیل ببینید و درس‌ها را در دفترچه بنویسید. بخش آموزش توضیح ساده دارد."], ["جائزہ لیں اور سیکھیں", "تجزیہ میں کامیابی کی شرح اور اوسط R دیکھیں اور سبق جرنل میں لکھیں۔ سیکھیں ٹیب میں آسان وضاحت ہے۔"], ["समीक्षा करें और सीखें", "विश्लेषण में सफलता दर और औसत R देखें और सीख जर्नल में लिखें। सीखें टैब में आसान व्याख्या है।"]]], "fg": [[["Choisir une société", "Dans Sociétés : « Aidez-moi à choisir » ou les filtres. Comparez côte à côte dans l'onglet Comparer."], ["Elige una empresa", "En Empresas: usa «Ayúdame a elegir» o los filtros. Compara lado a lado en la pestaña Comparar."], ["Firmanı seç", "Firmalar'da «Seçmeme yardım et» veya filtreleri kullan. Karşılaştır sekmesinde yan yana kıyasla."], ["شرکت را انتخاب کنید", "در شرکت‌ها از «کمکم کن انتخاب کنم» یا فیلترها استفاده کنید. در بخش مقایسه کنار هم ببینید."], ["کمپنی چنیں", "کمپنیاں میں «چننے میں مدد» یا فلٹر استعمال کریں۔ موازنہ ٹیب میں ساتھ ساتھ دیکھیں۔"], ["फर्म चुनें", "फर्म्स में «चुनने में मदद» या फ़िल्टर इस्तेमाल करें। तुलना टैब में साथ-साथ देखें।"]], [["Lire les règles", "Ouvrez la page de la société : limites de perte quotidienne et maximale et leur type (fixe ou glissante), avec la source officielle."], ["Lee las reglas", "Abre la página de la empresa: límites de pérdida diaria y máxima y su tipo (fija o móvil), con la fuente oficial."], ["Kuralları oku", "Firma sayfasını aç: günlük ve azami kayıp limitleri ve türü (sabit veya kayan), resmî kaynakla."], ["قوانین را بخوانید", "صفحه شرکت را باز کنید: حد ضرر روزانه و حداکثر و نوع آن (ثابت یا شناور) با منبع رسمی."], ["قواعد پڑھیں", "کمپنی کا صفحہ کھولیں: روزانہ اور زیادہ سے زیادہ نقصان کی حد اور اس کی قسم (مقررہ یا متحرک)، سرکاری ماخذ کے ساتھ۔"], ["नियम पढ़ें", "फर्म का पेज खोलें: दैनिक और अधिकतम नुकसान सीमा और उसका प्रकार (स्थिर या चलती), आधिकारिक स्रोत के साथ।"]], [["Régler le suivi du challenge", "Dans Outils : choisissez la société et saisissez votre solde pour voir la marge avant la limite de perte."], ["Configura el seguimiento", "En Herramientas: elige la empresa y pon tu saldo para ver el margen antes del límite de pérdida."], ["Challenge takibini ayarla", "Araçlar'da firmayı seç ve bakiyeni gir, kayıp limitine ne kadar kaldığını gör."], ["پیگیری چالش را تنظیم کنید", "در ابزارها شرکت را انتخاب و موجودی را وارد کنید تا فاصله تا حد ضرر را ببینید."], ["چیلنج ٹریکر سیٹ کریں", "ٹولز میں کمپنی چنیں اور بیلنس لکھیں تاکہ نقصان کی حد تک گنجائش دیکھ سکیں۔"], ["चैलेंज ट्रैकर सेट करें", "टूल्स में फर्म चुनें और बैलेंस डालें ताकि नुकसान सीमा तक बची जगह दिखे।"]], [["Analyser sur le graphique", "Touchez le graphique pour l'analyse complète : choisissez une paire et tracez vos niveaux."], ["Analiza en el gráfico", "Toca el gráfico para el análisis completo: elige un par y dibuja tus niveles."], ["Grafikte analiz et", "Tam analiz için grafiğe dokun: bir parite seç ve seviyelerini çiz."], ["روی نمودار تحلیل کنید", "برای تحلیل کامل روی نمودار بزنید: یک جفت‌ارز انتخاب و سطوح را رسم کنید."], ["چارٹ پر تجزیہ کریں", "مکمل تجزیے کے لیے چارٹ دبائیں: جوڑی چنیں اور اپنی سطحیں کھینچیں۔"], ["चार्ट पर विश्लेषण करें", "पूरे विश्लेषण के लिए चार्ट दबाएं: जोड़ी चुनें और अपने स्तर बनाएं।"]], [["Calculer le risque", "Dans Outils : calculez la taille de position avant d'entrer."], ["Calcula el riesgo", "En Herramientas: calcula el tamaño de posición antes de entrar."], ["Riski hesapla", "Araçlar'da girmeden önce pozisyon boyutunu hesapla."], ["ریسک را حساب کنید", "در ابزارها پیش از ورود حجم معامله را حساب کنید."], ["رسک کا حساب لگائیں", "ٹولز میں داخل ہونے سے پہلے پوزیشن سائز نکالیں۔"], ["रिस्क निकालें", "टूल्स में एंट्री से पहले पोज़ीशन साइज़ निकालें।"]], [["Noter vos trades", "Dans Analyse : le tableau des trades pour entrée, stop et sortie."], ["Registra tus operaciones", "En Análisis: la hoja de operaciones para entrada, stop y salida."], ["İşlemlerini kaydet", "Analiz'de giriş, zarar durdur ve çıkış için işlem tablosunu kullan."], ["معاملات را ثبت کنید", "در تحلیل: جدول معاملات برای ورود، حد ضرر و خروج."], ["ٹریڈز درج کریں", "تجزیہ میں: انٹری، اسٹاپ اور ایگزٹ کے لیے ٹریڈ شیٹ۔"], ["ट्रेड दर्ज करें", "विश्लेषण में: एंट्री, स्टॉप और एग्ज़िट के लिए ट्रेड शीट।"]], [["Vous évaluer", "Regardez le taux de réussite et le R moyen, et faites le point avant de continuer le challenge."], ["Evalúate", "Mira el porcentaje de acierto y el R medio y revisa antes de continuar el desafío."], ["Kendini değerlendir", "Başarı oranına ve ortalama R'ye bak, challenge'a devam etmeden önce gözden geçir."], ["خودتان را بسنجید", "درصد موفقیت و میانگین R را ببینید و پیش از ادامه چالش مرور کنید."], ["اپنا جائزہ لیں", "کامیابی کی شرح اور اوسط R دیکھیں اور چیلنج جاری رکھنے سے پہلے جائزہ لیں۔"], ["खुद की समीक्षा करें", "सफलता दर और औसत R देखें और चैलेंज जारी रखने से पहले समीक्षा करें।"]]], "ttl": {"wf": ["Comment commencer (la routine)", "Cómo empezar (la rutina)", "Nasıl başlanır (düzen)", "چگونه شروع کنیم (روال)", "شروع کیسے کریں (ترتیب)", "कैसे शुरू करें (क्रम)"], "fg": ["Comment commencer (pas à pas)", "Cómo empezar (paso a paso)", "Nasıl başlanır (adım adım)", "چگونه شروع کنیم (گام به گام)", "شروع کیسے کریں (قدم بہ قدم)", "कैसे शुरू करें (कदम दर कदम)"]}, "dis": {"wf": ["Ceci est une routine de travail basée sur notre expérience chez WEAM FX. Ce n'est ni une recommandation d'achat ou de vente ni un conseil financier. Le trading est très risqué et chaque décision vous appartient.", "Esta es una rutina de trabajo basada en nuestra experiencia en WEAM FX. No es una recomendación de compra o venta ni asesoramiento financiero. El trading es de alto riesgo y cada decisión es tuya.", "Bu, WEAM FX deneyimimize dayanan bir çalışma düzenidir. Alım satım tavsiyesi veya finansal danışmanlık değildir. İşlem yüksek risklidir ve her karar sana aittir.", "این یک روال کاری بر پایه تجربه ما در WEAM FX است. توصیه خرید یا فروش یا مشاوره مالی نیست. معامله پرریسک است و هر تصمیم با شماست.", "یہ WEAM FX میں ہمارے تجربے پر مبنی ایک طریقہ کار ہے۔ یہ خرید و فروخت کی سفارش یا مالی مشورہ نہیں۔ ٹریڈنگ میں زیادہ خطرہ ہے اور ہر فیصلہ آپ کا ہے۔", "यह WEAM FX में हमारे अनुभव पर आधारित एक कार्य-क्रम है। यह खरीद-बिक्री की सलाह या वित्तीय सलाह नहीं है। ट्रेडिंग में जोखिम अधिक है और हर फैसला आपका है।"], "fg": ["Ceci est un ordre d'utilisation suggéré, basé sur notre expérience, ni une recommandation ni un conseil financier. Le trading est très risqué et chaque décision vous appartient.", "Este es un orden de uso sugerido, basado en nuestra experiencia; no es una recomendación ni asesoramiento financiero. El trading es de alto riesgo y cada decisión es tuya.", "Bu, deneyimimize dayanan önerilen bir kullanım sırasıdır; tavsiye veya finansal danışmanlık değildir. İşlem yüksek risklidir ve her karar sana aittir.", "این ترتیب پیشنهادی استفاده بر پایه تجربه ماست، توصیه یا مشاوره مالی نیست. معامله پرریسک است و هر تصمیم با شماست.", "یہ ہمارے تجربے پر مبنی استعمال کی تجویز کردہ ترتیب ہے، سفارش یا مالی مشورہ نہیں۔ ٹریڈنگ میں زیادہ خطرہ ہے اور ہر فیصلہ آپ کا ہے۔", "यह हमारे अनुभव पर आधारित उपयोग का सुझाया क्रम है, सलाह या वित्तीय सलाह नहीं। ट्रेडिंग में जोखिम अधिक है और हर फैसला आपका है।"]}};
